@app.cell
def __(REPO, body, button, mo, title, token):
    # The button's value is read outside the cell that built it.
    def _file():
        import json as _json
        import urllib.error
        import urllib.request as _req

        if not token.value:
            return f"No token entered — copy the preview above and file it at https://github.com/{REPO}/issues/new"
        payload = _json.dumps({"title": title, "body": body}).encode()
        req = _req.Request(
            f"https://api.github.com/repos/{REPO}/issues",
            data=payload,
            method="POST",
            headers={
                "Authorization": f"Bearer {token.value}",
                "Accept": "application/vnd.github+json",
                "Content-Type": "application/json",
                "User-Agent": "anthropic-pbc-edit-plane",
            },
        )
        try:
            with _req.urlopen(req, timeout=30) as resp:
                return f"Filed: {_json.loads(resp.read().decode())['html_url']}"
        except urllib.error.HTTPError as exc:
            return f"GitHub refused it ({exc.code}): {exc.read().decode()[:400]}"
        except Exception as exc:
            return f"Could not file — {type(exc).__name__}: {exc}"

    out = mo.md(f"**{_file()}**") if button.value else mo.md("_Not filed yet._")
    out
    return

