"""Composable HTML primitives, using only the Python standard library.

These return escaped markup, not a framework, DOM model, auth layer or publisher.
"""
from html import escape
import json
from urllib.parse import urlsplit
from design.publishers import profile


def link(href, label):
    parsed = urlsplit(href)
    if parsed.scheme not in ('', 'http', 'https') or href.startswith('//') or any(ord(c) < 32 for c in href):
        raise ValueError('Links must be local or HTTP(S) references')
    return f'<a href="{escape(href, quote=True)}">{escape(str(label))}</a>'


def navigation(items):
    return '<nav class="reference-nav" aria-label="Page navigation">' + ''.join(link(href, label) for href, label in items) + '</nav>'


def masthead(publication='working', caption='Working papers and collaboration', assets='assets', publisher=None):
    if publication not in ('working', 'official'):
        raise ValueError('Unknown publication treatment')
    identity = profile(publisher, publication)
    filename, name = identity['logo'], identity['name']
    css = ' class="praxis-mark"' if identity['id'] == 'praxis' else ''
    return f'<header class="masthead"><img{css} src="{assets}/{filename}" alt="{name}"><p>{escape(caption)}</p></header>'


def footer(assets='assets'):
    return f'<footer class="site-footer"><a href="https://ethicic.com" aria-label="Ethical Capital website"><img src="{assets}/ethical-capital.svg" alt="Ethical Capital"></a><div><p>Praxis is a home for working papers, experiments and collaboration.</p><p>Official Ethical Capital opinions are explicitly released and versioned. Hosting a paper here does not make it an official firm publication.</p><p class="footer-meta">Hosted by Ethical Capital · praxis.ethicic.com</p><p class="footer-meta"><a href="sustainability.html">Hosting and resource disclosure</a> · <a href="carbon.txt">carbon.txt</a> · <a href="archive.html">Archived editions</a></p></div></footer>'


def publication_label(kind, version=None, publisher=None):
    if kind == 'working':
        return 'Working paper · open for collaboration'
    if kind != 'official' or not isinstance(version, str) or not version.strip():
        raise ValueError('An official treatment needs an explicit version')
    # Prepared files must not pretend that rendering itself issued a firm opinion.
    return f'{profile(publisher, kind)["name"]} release preview · version {version}'


def work_list(records):
    return '<ul class="work-list">' + ''.join('<li>' + link(record['id'] + '.html', record['title']) + '<p class="subtitle">' + escape(publication_label(record.get('publication', 'working'), record.get('version'), record.get('publisher'))) + '</p></li>' for record in records) + '</ul>'


def attribution(title, locator, digest, download, provenance="Origin metadata not supplied.", source_url=None, as_of="Not supplied"):
    return '<div class="source-attribution"><p>' + link(download, 'Download source: ' + title) + '</p><dl><dt>Origin</dt><dd>' + escape(provenance) + (' · ' + link(source_url, 'Original source') if source_url else '') + '</dd><dt>As of</dt><dd>' + escape(as_of) + '</dd><dt>Locator</dt><dd>' + escape(locator) + '</dd><dt>SHA-256</dt><dd><code>' + escape(digest) + '</code></dd><dt>Assurance</dt><dd>Local bytes pinned. No signature verification or quantitative review is claimed.</dd></dl></div>'


def shell(title, content, publication='working', caption=None, linked_data=None, publisher=None):
    structured = ''
    if linked_data is not None:
        encoded = json.dumps(linked_data, ensure_ascii=False, sort_keys=True, separators=(',', ':')).replace('<', '\\u003c')
        structured = '<script type="application/ld+json">' + encoded + '</script>'
    identity = profile(publisher, publication)
    return '<!doctype html>\n<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>' + escape(title) + '</title><link rel="stylesheet" href="assets/praxis.css"><link rel="alternate" type="application/ld+json" href="graph.jsonld" title="Selected linked data">' + structured + '</head><body class="praxis" data-publication="' + publication + '" data-publisher="' + identity['id'] + '"><a class="skip-link" href="#main">Skip to content</a><main id="main">' + masthead(publication, caption or 'Working papers and collaboration', publisher=identity['id']) + content + footer() + '</main></body></html>\n'

