import marimo

__generated_with = "0.23.2"
app = marimo.App(
    width="medium",
    app_title="The argument's gaps — Anthropic PBC edit plane",
)


@app.cell
def __():
    """The argument's edit plane: three ways to read the paper's argument.

    **Chain** — every claim with what stands under it, worst gaps first.
    **Cards** — one card per argument unit, in the Praxis argument-unit form
    (id, kind, statement, qualifications, evidence refs, a second representation).
    **Logic** — the argument as propositional logic: atoms, premises, a derivation
    chain and a truth table, to see where entailment actually breaks.

    The notebook reads the repository and never writes to it. Gaps you find become
    GitHub issues; the paper changes when someone acts on it, with review.

    Design follows the Praxis primitive (`design/praxis.css`): the tokens in
    `docs/notebooks/praxis-tokens.css` are generated from it by
    `scripts/praxis_tokens.py`, so the palette and scale are Praxis's own.
    """
    import marimo as mo

    return (mo,)


@app.cell
def __(mo):
    """Load the Praxis tokens and the stylesheet that binds them to the notebook."""
    import pathlib

    _here = pathlib.Path(__file__).resolve().parent

    def _read(name):
        path = _here / name
        return path.read_text(encoding="utf-8") if path.exists() else None

    # The tokens are generated from Praxis design/praxis.css. Missing them is a
    # finding, not something to paper over with an invented palette.
    praxis_tokens = _read("praxis-tokens.css")
    tokens_status = (
        "Praxis tokens loaded from `praxis-tokens.css`"
        if praxis_tokens
        else "Praxis tokens missing — run `uv run scripts/praxis_tokens.py emit`"
    )

    # Layout styles built only from Praxis custom properties: no literal colour,
    # size or font appears below, so the notebook inherits the primitive.
    praxis_css = """
    .praxis-plane {
      margin: 0;
      padding: var(--space-section) var(--page-gutter);
      background: var(--paper);
      color: var(--ink);
      font: var(--type-body)/var(--leading-reading) var(--font-reading);
      max-width: var(--page-width);
    }
    .praxis-plane ::selection { background: var(--ink); color: var(--paper); }
    .praxis-plane a { color: inherit; text-underline-offset: 4px; }
    .praxis-plane a:hover { color: var(--accent); }
    .praxis-plane h1, .praxis-plane h2, .praxis-plane h3 { text-wrap: balance; font-weight: 400; }
    .praxis-plane h1 { font-size: var(--type-title); margin: 0 0 var(--space-small); line-height: 1.2; }
    .praxis-plane h2 { font-size: var(--type-section); letter-spacing: -.025em; line-height: 1.2;
      margin: 0 0 var(--space-small); }
    .praxis-plane h3 { font-size: var(--type-body); margin: 0 0 var(--space-small); }
    .praxis-plane p { max-width: var(--measure); margin: var(--space-small) 0; }
    .praxis-plane .meta { font: var(--type-small)/1.6 var(--font-label); color: var(--muted); }
    .praxis-plane .intro { max-width: 58ch; font-size: clamp(20px, 2vw, 24px); line-height: 1.5; }

    /* One card per argument unit (design/argument-units.md). */
    .unit-grid { display: grid; gap: var(--space-group); margin: var(--space-group) 0; }
    .unit-card {
      border-top: 1px solid var(--rule);
      padding-top: var(--space-small);
      background: var(--paper);
    }
    .unit-card[data-state='fails'], .unit-card[data-state='unsupported'] {
      border-top-color: var(--accent);
    }
    .unit-head { display: flex; gap: var(--space-small); align-items: baseline;
      flex-wrap: wrap; justify-content: space-between; }
    .unit-id { font: var(--type-small)/1.5 var(--font-data); color: var(--muted); }
    .unit-kind {
      font: var(--type-small)/1.5 var(--font-label);
      color: var(--paper); background: var(--accent);
      padding: 2px 8px; letter-spacing: .04em; text-transform: uppercase;
    }
    .unit-kind[data-kind='question'] { background: var(--muted); }
    .unit-statement { font-size: var(--type-body); margin: var(--space-small) 0; max-width: var(--measure); }
    .unit-needs { font: var(--type-small)/1.6 var(--font-label); color: var(--muted); }
    .unit-needs code, .unit-fail code { font-family: var(--font-data); }
    .unit-fail { margin-top: var(--space-small); padding: var(--space-small);
      background: var(--wash); border-left: 2px solid var(--accent); font-size: var(--type-small); }
    .unit-fail ul { margin: var(--space-small) 0 0; padding-left: 18px; }
    .unit-fail li { margin: 4px 0; max-width: var(--measure); }
    .unit-reps { margin-top: var(--space-small); font: var(--type-small)/1.6 var(--font-label); color: var(--muted); }
    .badge { display: inline-block; border: 1px solid var(--rule); padding: 1px 7px;
      margin-right: 6px; font: var(--type-small)/1.5 var(--font-label); }
    .badge[data-have='yes'] { border-color: var(--accent); color: var(--accent); }
    .praxis-plane table { border-collapse: collapse; width: 100%; margin: var(--space-small) 0;
      font: var(--type-small)/1.6 var(--font-label); }
    .praxis-plane caption { text-align: left; padding-bottom: 10px; color: var(--muted); }
    .praxis-plane th, .praxis-plane td { text-align: left; vertical-align: top;
      padding: 8px 12px 8px 0; border-bottom: 1px solid var(--rule); }
    .praxis-plane th { font-weight: 600; }
    .praxis-plane code, .praxis-plane .formula { font-family: var(--font-data); }
    .praxis-plane .verdict { font: var(--type-small)/1.6 var(--font-label); }
    .praxis-plane .verdict[data-valid='no'] { color: var(--accent); }
    """

    # The notebook renders inside an iframe-ish app shell; the primitive's own
    # body reset would fight it, so the tokens are scoped to `.praxis-plane`.
    mo.Html(f"<style>{praxis_tokens or ''}{praxis_css}</style>")
