@app.cell
def __(mo):
    token = mo.ui.text(
        kind="password",
        label="GitHub token (issues: write) — optional",
        placeholder="github_pat_…",
        full_width=True,
    )
    token
    return (token,)


@app.cell
def __(ARTIFACT_URL, BRANCH, PAPER_URL):
    """Read the artifact and the paper. Local checkout first, then the branch."""
    import json
    import pathlib
    import urllib.request

    def _get(url):
        req = urllib.request.Request(url, headers={"User-Agent": "anthropic-pbc-edit-plane"})
        with urllib.request.urlopen(req, timeout=30) as resp:
            return resp.read().decode("utf-8")

    root = pathlib.Path(__file__).resolve().parent.parent.parent

    def _local(name):
        path = root / name
        return path.read_text(encoding="utf-8") if path.exists() else None

    argument = {}
    artifact_error = ""
    artifact_source = ""
    local_artifact = _local("argument.json")
    if local_artifact is not None:
        try:
            argument = json.loads(local_artifact)
            artifact_source = "the working tree"
        except Exception as exc:
            artifact_error = f"local argument.json unreadable — {type(exc).__name__}: {exc}"
    if not argument and not artifact_error:
        try:
            argument = json.loads(_get(ARTIFACT_URL))
            artifact_source = BRANCH
        except Exception as exc:
            artifact_error = f"{type(exc).__name__}: {exc}"

    if argument:
        artifact_status = (
            f"loaded `argument.json` from {artifact_source} "
            f"({argument['counts']['premises']} premises)"
        )
    else:
        artifact_status = f"could not load `argument.json` — {artifact_error}"

    paper_text = ""
    try:
        paper_text = _local("docs/anthropic-contrapunctus.md") or _get(PAPER_URL)
        paper_status = f"loaded the paper ({len(paper_text):,} characters)"
    except Exception as exc:
        paper_status = f"could not load the paper — {type(exc).__name__}: {exc}"

    claims_digest = (
        argument.get("source", {})
        .get("inputs_blake3", {})
        .get("claims/anthropic-contrapunctus.tsv", "unknown")
        if argument
        else "unknown"
    )

    return argument, artifact_error, artifact_status, claims_digest, paper_status, paper_text


@app.cell
def __(argument, artifact_error, claims_digest, mo, paper_status, tokens_status):
    """The header, in the Praxis masthead form."""
    if artifact_error:
        header = mo.Html(
            f"""<div class="praxis-plane">
            <h1>The argument's gaps</h1>
