    if artifact_error or chosen != "cards":
        cards = mo.md("")
    else:
        by_label = {p["label"]: p for p in argument["premises"]}
        blocks = []
        for p in argument["premises"]:
            # kind: the standard's vocabulary, inferred from the row's role and state.
            if p["role"] == "thesis":
                kind = "inference"
            elif p["role"] == "remedy":
                kind = "recommendation"
            elif p["unsupported"] or p["fails"]:
                kind = "observation"
            else:
                kind = "observation"

            state = "unsupported" if p["unsupported"] else ("fails" if p["fails"] else "stands")

            needs = (
                ", ".join(f"<code>{r}</code>" for r in p["rests_on"])
                or "<em>nothing — this premise stands on no evidence</em>"
            )

            qualifications = []
            if p["unsupported"]:
                qualifications.append(
                    "No supporting claim: the premise is stated without anything under it."
                )
