                fail_block = (
                    f'<div class="unit-fail"><strong>Why it does not stand</strong>'
                    f"<ul>{items}</ul></div>"
                )

            # Evidence references: the quotation rows this claim leans on.
            evidence = p["rests_on_evidence"]
            evidence_html = (
                ", ".join(f"<code>{e}</code>" for e in evidence) if evidence else "<em>none</em>"
            )

            # Representations: prose always; a table when it has nested claims;
            # a formula when it is an inference.
            reps = [("prose", True)]
            reps.append(("table", bool(p["rests_on_premises"] or evidence)))
            reps.append(("diagram", False))
            badge_row = "".join(
