            + f"<td>{'T' if ap else 'F'}</td><td>{'T' if c else 'F'}</td></tr>"
            for combo, ap, c in logic["rows"]
        )
        head = "".join(f"<th><code>{s}</code></th>" for s in logic["leaves"])
        verdict = "VALID" if logic["valid"] else "INVALID"
        logic_view = mo.Html(
            f"""<div class="praxis-plane">
            <h2>Formal logic</h2>
            <p>The same argument as propositional atoms. A premise holds only when
            every premise beneath it holds — <code>rests_on</code> is a conjunction —
            so the conclusion follows exactly when the leaf premises force the
            thesis.</p>

            <h3>1 · Atomic propositions</h3>
            <table><caption>Each premise, as an atom</caption>
              <thead><tr><th>Symbol</th><th>Proposition</th></tr></thead>
              <tbody>{atom_rows}</tbody></table>

            <h3>2 · Truth table</h3>
            <p>Rows evaluated: <strong>{len(logic["rows"])}</strong> ·
               Counterexamples: <strong>{logic["counterexamples"]}</strong> ·
               Argument is <span class="verdict" data-valid="{"yes" if logic["valid"] else "no"}">
               <strong>{verdict}</strong></span></p>
            <table>
              <caption>Every assignment of the leaf premises</caption>
              <thead><tr>{head}<th>All premises</th><th>Conclusion ({logic["thesis"]})</th></tr></thead>
              <tbody>{tt_rows}</tbody></table>

            <h3>3 · Reading the result</h3>
            <p>A row with every premise true and the conclusion false is a
            counterexample: it names the assignment under which the argument fails.
            Where the table is invalid, the gap is in a premise that carries the
            conclusion on a branch another premise already satisfies — the same gap
            the cards name, said in symbols.</p>
            <p>Leaf premises under the thesis: <code>{", ".join(logic["leaves"])}</code>.
            This view is generated from <code>argument.json</code>; it does not restate
            the argument by hand.</p>
            </div>"""
        )
    logic_view
    return


