        <p class="meta">This posts to <code>github.com/{REPO}/issues</code>. Nothing is
        written to the repository itself: an issue is the open record of a proposed
        gap, and the paper changes only when someone acts on it and it is reviewed.
        </p></div>"""
    )
    button
    return (button,)


@app.cell
def __(REPO, body, button, mo, title, token):
    def _file():
        import json as _json
        import urllib.error
        import urllib.request as _req

        if not token.value:
            return (
                "No token entered — copy the preview above and file it at "
                f"https://github.com/{REPO}/issues/new"
            )
        payload = _json.dumps({"title": title, "body": body}).encode()
        req = _req.Request(
            f"https://api.github.com/repos/{REPO}/issues",
            data=payload,
            method="POST",
            headers={
                "Authorization": f"Bearer {token.value}",
                "Accept": "application/vnd.github+json",
                "Content-Type": "application/json",
                "User-Agent": "anthropic-pbc-edit-plane",
            },
        )
        try:
            with _req.urlopen(req, timeout=30) as resp:
                return f"Filed: {_json.loads(resp.read().decode())['html_url']}"
        except urllib.error.HTTPError as exc:
            return f"GitHub refused it ({exc.code}): {exc.read().decode()[:400]}"
        except Exception as exc:
            return f"Could not file — {type(exc).__name__}: {exc}"

    result = (
        mo.Html(f'<div class="praxis-plane"><p>{_file()}</p></div>')
        if button.value
        else mo.Html('<div class="praxis-plane"><p class="meta">Not filed yet.</p></div>')
    )
    result
    return


