import colorsys


def lum(h):
    h = h.lstrip("#")
    r, g, b = [int(h[i:i + 2], 16) / 255 for i in (0, 2, 4)]

    def f(c):
        return c / 12.92 if c <= 0.03928 else ((c + 0.055) / 1.055) ** 2.4

    return 0.2126 * f(r) + 0.7152 * f(g) + 0.0722 * f(b)


def ratio(a, b):
    la, lb = lum(a), lum(b)
    hi, lo = max(la, lb), min(la, lb)
    return (hi + 0.05) / (lo + 0.05)


def to_hex(r, g, b):
    return "#{:02x}{:02x}{:02x}".format(
        min(255, round(r * 255)), min(255, round(g * 255)), min(255, round(b * 255))
    )


def darken_keep_hue(hexs, bg, target=7.0):
    """Darken toward the background, keeping hue and saturation, until target is met."""
    h = hexs.lstrip("#")
    r, g, b = [int(h[i:i + 2], 16) / 255 for i in (0, 2, 4)]
    hh, ll, ss = colorsys.rgb_to_hls(r, g, b)
    for i in range(0, 1001):
        cand = to_hex(*colorsys.hls_to_rgb(hh, ll * (1 - i / 1000), ss))
        if ratio(cand, bg) >= target:
            return cand, ratio(cand, bg)
    return hexs, ratio(hexs, bg)


CASES = [
    ("muted light / paper", "#5f5f5f", "#fff"),
    ("muted light / wash", "#5f5f5f", "#f3f3f3"),
    ("muted ec / paper", "#64566f", "#f0ebf6"),
    ("muted ec / wash", "#64566f", "#e5dcee"),
    ("accent ec / paper", "#286862", "#f0ebf6"),
    ("accent ec / wash", "#286862", "#e5dcee"),
]

for name, fg, bg in CASES:
    out, r = darken_keep_hue(fg, bg)
    print(f"{name:22} {fg} -> {out}  {r:5.2f}:1  (was {ratio(fg, bg):5.2f}:1)")

